494	/// `--step`: pause between stages so the user can inspect the repos
495	/// before the next one runs. `--yes` passes the gates, and a non-tty
496	/// without it is an error rather than a hang.
497	fn step_gate(
498	    params: &PushParams,
499	    done: &str,
500	    next: &str,
501	) -> Result<(), Box<dyn std::error::Error>> {
502	    if !params.step {
503	        return Ok(());
504	    }
505	    if params.yes {
506	        debug!("push step: --yes skips step gate between {done} and {next}");
507	        return Ok(());
508	    }
509	    if !is_stdin_tty() {
510	        return Err("push: --step requires a tty (stdin is not interactive); \
511	                    add --yes to bypass step gates in non-interactive contexts"
512	            .into());
513	    }
514	    let answer = prompt(&format!(
515	        "push step: {done} done. Continue to {next}? [y/N] "
516	    ))?;
517	    let normalized = answer.trim().to_ascii_lowercase();
518	    if normalized != "y" && normalized != "yes" {
519	        return Err(format!("push: step gate declined after {done} (got {answer:?})").into());
520	    }
521	    Ok(())
522	}
523	
524	/// Verify the world matches what the halves claim: the work
525	/// bookmark at the work commit and the work `@` empty unless it held
526	/// new work when the run began, and the agent `main` at the partner. The agent `@` may hold new session writes
527	/// that landed after the squash, so it is not checked.
528	fn verify_completion(pair: &Pair, run: &Run) -> Result<(), Box<dyn std::error::Error>> {
529	    if let Some((bookmark, work_chid)) = &run.work {
530	        let actual = jj::chid_of(&pair.work, bookmark)?;
531	        if actual != *work_chid {
532	            return Err(format!(
533	                "completion sanity: work bookmark '{bookmark}' is at chid '{actual}' but this \
534	                 run published '{work_chid}'."
535	            )
536	            .into());
537	        }
538	        if !run.held && !jj::is_empty(&pair.work, "@")? {
539	            let wc_diff = jj::diff_stat(&pair.work)?;
540	            return Err(format!(
541	                "completion sanity: work working copy has uncommitted changes. Diff stat:\n{wc_diff}"
542	            )
543	            .into());
544	        }
545	    }
546	    if let Some(partner) = &run.partner {
547	        let actual = jj::chid_of(&pair.agent, BOT_BOOKMARK)?;
548	        if actual != *partner {
549	            return Err(format!(
550	                "completion sanity: agent bookmark '{BOT_BOOKMARK}' is at chid '{actual}' but \
551	                 this run published '{partner}'."
552	            )
553	            .into());
554	        }
555	    }
556	    Ok(())
557	}
