559	/// `push -s p`: a plain repo's `@-` goes out on its bookmark, no
560	/// trailer asked for, the work half's checks otherwise.
561	fn push_por(
562	    ctx: &mut Context,
563	    repo: &Path,
564	    params: &PushParams,
565	) -> Result<(), Box<dyn std::error::Error>> {
566	    if !jj::is_empty(repo, "@")? {
567	        info!("push -s p: @ holds new work, left as it is, and @- is what goes out");
568	    }
569	    if jj::desc_of(repo, "@-")?.trim().is_empty() {
570	        return Err("push -s p: @- has no description, so it is not a commit to publish".into());
571	    }
572	    let bookmark = match &params.bookmark {
573	        Some(b) => b.clone(),
574	        None => crate::squash_push::current_bookmark(repo, "@-")?,
575	    };
576	    let arg = repo.to_string_lossy();
577	    if params.dry_run {
578	        info!(
579	            "push: [dry-run] would run jj bookmark set {bookmark} -r @- -R {arg}, then git push --bookmark {bookmark}"
580	        );
581	        return Ok(());
582	    }
583	    info!("push bookmark-set: bookmark set {bookmark} -r @- -R {arg}");
584	    ctx.session(repo)?.bookmark_set(&bookmark, "@-")?;
585	    crate::common::verify_tracking(repo, &bookmark)?;
586	    info!("push push-work: git push --bookmark {bookmark} -R {arg}");
587	    ctx.session(repo)?.git_push_bookmark(&bookmark)?;
588	    info!("push: completed");
589	    Ok(())
590	}
