1	//! Integration tests for the push module.
2	//!
3	//! End-to-end tests for `push_in` against real dual-repo jj
4	//! fixtures (bare-git remotes + colocated jj repos under a unique
5	//! tempdir via `crate::test_helpers::Fixture`). The pair is made by
6	//! `commit::commit`, the way a rung's is, and push publishes it.
7	//!
8	//! Requires `jj` and the compiled `vc-x1` binary in `PATH`.
9	
10	use super::*;
11	use crate::commit::{CommitParams, Target, commit};
12	use crate::options_flags::scope::Side;
13	use crate::test_helpers::{Fixture, FixturePor, chid, cid, description, jj_ok, test_ctx};
14	use std::fs;
15	
16	/// First line of a revision's description.
17	fn desc_first_line(repo: &Path, rev: &str) -> String {
18	    jj_ok(
19	        repo,
20	        &[
21	            "log",
22	            "-r",
23	            rev,
24	            "--no-graph",
25	            "-T",
26	            "description.first_line()",
27	        ],
28	    )
29	}
30	
31	/// Whether a revision's working copy is empty.
32	fn is_empty(repo: &Path, rev: &str) -> bool {
33	    jj_ok(repo, &["log", "-r", rev, "--no-graph", "-T", "empty"]) == "true"
34	}
35	
36	/// The fixture's pair, by the paths the resolver would give.
37	fn pair(fx: &Fixture) -> Pair {
38	    Pair {
39	        work: fx.work.clone(),
40	        agent: fx.bot.clone(),
41	    }
42	}
43	
44	/// Both sides, work first.
45	fn both() -> Scope {
46	    Scope(vec![Side::Work, Side::Bot])
47	}
48	
49	/// Standard test params: the line's bookmark, `-s b`, no gates.
50	fn test_params() -> PushParams {
51	    PushParams {
52	        bookmark: None,
53	        repo: None,
54	        scope: RepoScope::Sides(both()),
55	        step: false,
56	        dry_run: false,
57	        yes: true,
58	    }
59	}
60	
61	/// Make a rung's pair in the fixture the way `commit` does: a work
62	/// file and a session line, then `commit -s b` (`agent_now`) or
63	/// `-s w`. Returns the work and agent `@` change ids read before
64	/// the commit, which the commits keep. No bookmark is advanced, so
65	/// the line stays as the test arranged it for push to resolve.
66	fn make_pair(fx: &Fixture, title: &str, agent_now: bool) -> (String, String) {
67	    fs::write(fx.work.join(format!("{}.txt", title.len())), title).expect("write work file");
68	    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write session file");
69	    let work_at = chid(&fx.work, "@");
70	    let agent_at = chid(&fx.bot, "@");
71	    let params = CommitParams {
72	        target: Target::Pair {
73	            pair: pair(fx),
74	            agent_now,
75	        },
76	        title: Some(title.to_string()),
77	        body: Some("The problem.\n\n* A facet.\n  - Its solution.\n".to_string()),
78	        closing: None,
79	        opening: None,
80	        advance: crate::commit::Advance::Off,
81	        push: Some(false),
82	        land: None,
83	        skip: None,
84	        dry_run: false,
85	        rev: None,
86	    };
87	    commit(&mut test_ctx(), &params).expect("the pair is made");
88	    (work_at, agent_at)
89	}
90	
91	/// A pair made at once: push folds the journal that landed after
92	/// the commit into the partner, keeps its change id, and publishes
93	/// both bookmarks.
94	#[test]
95	fn push_publishes_a_pair_made_at_once() {
96	    let fx = Fixture::new("push-pair-b");
97	    let (work_at, agent_at) = make_pair(&fx, "feat: at once", true);
98	    fs::write(fx.bot.join("tail.jsonl"), "{\"line\":2}\n").expect("write tail");
99	
100	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("push");
101	
102	    assert_eq!(chid(&fx.work, "main"), work_at);
103	    assert_eq!(cid(&fx.work, "main@origin"), cid(&fx.work, "main"));
104	    assert_eq!(desc_first_line(&fx.work, "main"), "feat: at once");
105	    assert_eq!(chid(&fx.bot, "main"), agent_at, "the partner keeps its id");
106	    assert_eq!(cid(&fx.bot, "main@origin"), cid(&fx.bot, "main"));
107	    let files = jj_ok(&fx.bot, &["file", "list", "-r", "main"]);
108	    assert!(files.contains("tail.jsonl"), "tail not folded:\n{files}");
109	    assert!(is_empty(&fx.work, "@") && is_empty(&fx.bot, "@"));
110	}
111	
112	/// A pair made in two steps: push commits the journal as the
113	/// partner, with the work commit's description and a trailer naming
114	/// it, at the change id the work commit already names.
115	#[test]
116	fn push_completes_a_pair_made_in_two_steps() {
117	    let fx = Fixture::new("push-pair-w");
118	    let (work_at, agent_at) = make_pair(&fx, "feat: two steps", false);
119	    assert!(!is_empty(&fx.bot, "@"), "the journal is still in @");
120	
121	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("push");
122	
123	    assert_eq!(chid(&fx.work, "main"), work_at);
124	    assert_eq!(
125	        chid(&fx.bot, "main"),
126	        agent_at,
127	        "the journal became the named partner"
128	    );
129	    assert_eq!(desc_first_line(&fx.bot, "main"), "feat: two steps");
130	    let agent_desc = description(&fx.bot, "main");
131	    assert!(
132	        agent_desc
133	            .trim_end()
134	            .ends_with(&format!("ochid: /{work_at}")),
135	        "{agent_desc}"
136	    );
137	    assert_eq!(agent_desc.matches("ochid:").count(), 1, "{agent_desc}");
138	    assert!(
139	        agent_desc.contains("The problem.\n\n* A facet."),
140	        "{agent_desc}"
141	    );
142	    let work_desc = description(&fx.work, "main");
143	    assert!(
144	        work_desc
145	            .trim_end()
146	            .ends_with(&format!("ochid: /.claude/{agent_at}")),
147	        "{work_desc}"
148	    );
149	    assert_eq!(cid(&fx.bot, "main@origin"), cid(&fx.bot, "main"));
150	
151	    let check = crate::validate_desc::ValidateDescParams {
152	        pos_rev: None,
153	        pos_count: None,
154	        revision: "main".to_string(),
155	        limit: None,
156	        repos: vec![
157	            ("work".to_string(), fx.work.clone()),
158	            ("agent".to_string(), fx.bot.clone()),
159	        ],
160	        other_repo: None,
161	        id_len: crate::desc_helpers::DEFAULT_ID_LEN,
162	    };
163	    crate::validate_desc::validate_desc(&test_ctx(), &check).expect("both directions valid");
164	}
165	
166	/// New work in the work `@` is the next rung's: push publishes the
167	/// pair at `@-` and leaves `@` as it is, its change, its file, and its
168	/// place above the commit, through a restamp that rewrites `@-`.
169	#[test]
170	fn push_leaves_new_work_in_at() {
171	    let fx = Fixture::new("push-new-work");
172	    let (work_at, _) = make_pair(&fx, "feat: then more", false);
173	    jj_ok(&fx.bot, &["commit", "-m", "an unrelated agent commit"]);
174	    fs::write(fx.work.join("more.txt"), "the next rung").expect("write");
175	    let next = chid(&fx.work, "@");
176	
177	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("push");
178	
179	    assert_eq!(chid(&fx.work, "main"), work_at);
180	    assert_eq!(cid(&fx.work, "main@origin"), cid(&fx.work, "main"));
181	    assert_eq!(chid(&fx.work, "@"), next, "@ keeps its change");
182	    assert_eq!(chid(&fx.work, "@-"), work_at, "@ stays above the commit");
183	    let files = jj_ok(&fx.work, &["diff", "--name-only", "-r", "@"]);
184	    assert!(
185	        files.lines().count() == 1 && files.ends_with("more.txt"),
186	        "@ keeps its work:\n{files}"
187	    );
188	    let pushed = jj_ok(&fx.work, &["file", "list", "-r", "main"]);
189	    assert!(!pushed.contains("more.txt"), "@ went out:\n{pushed}");
190	}
191	
192	/// A revision named as the bookmark, `@-`, is refused before anything
193	/// moves, the error saying push finds the bookmark itself.
194	#[test]
195	fn push_refuses_a_revision_as_the_bookmark() {
196	    let fx = Fixture::new("push-revision");
197	    make_pair(&fx, "feat: by revision", true);
198	    let work_main = cid(&fx.work, "main");
199	    let mut params = test_params();
200	    params.bookmark = Some("@-".to_string());
201	
202	    let err = push(
203	        &mut test_ctx(),
204	        &PushParams {
205	            repo: Some(fx.work.clone()),
206	            ..params
207	        },
208	    )
209	    .expect_err("refused")
210	    .to_string();
211	    assert!(err.contains("is a revision, not a bookmark"), "{err}");
212	    assert!(err.contains("leave it out"), "{err}");
213	    assert_eq!(cid(&fx.work, "main"), work_main);
214	}
215	
216	/// A work `@-` with no trailer is not a pair's commit, and the error
217	/// names the command that makes one.
218	#[test]
219	fn push_refuses_an_unpaired_commit() {
220	    let fx = Fixture::new("push-unpaired");
221	    fs::write(fx.work.join("hand.txt"), "hand-made").expect("write");
222	    jj_ok(&fx.work, &["commit", "-m", "feat: by hand"]);
223	    let err = push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params())
224	        .expect_err("refused")
225	        .to_string();
226	    assert!(err.contains("no `ochid:` trailer"), "{err}");
227	    assert!(err.contains("vc-x1 commit"), "{err}");
228	}
229	
230	/// The agent repo changed between `commit -s w` and the push, so the
231	/// change the work commit names is gone: push restamps the
232	/// unpublished work commit with the agent `@`'s id, says so, and
233	/// commits the journal as the partner.
234	#[test]
235	fn push_restamps_when_the_agent_at_changed() {
236	    let fx = Fixture::new("push-restamp");
237	    let (work_at, stamped) = make_pair(&fx, "feat: restamped", false);
238	    // A commit in the agent repo by hand: @ becomes a new change, and
239	    // @- is the old one under another description, so neither names
240	    // the work commit nor is the change it names.
241	    jj_ok(&fx.bot, &["commit", "-m", "an unrelated agent commit"]);
242	    fs::write(fx.bot.join("more.jsonl"), "{\"line\":3}\n").expect("write");
243	    let agent_at = chid(&fx.bot, "@");
244	    assert_ne!(agent_at, stamped);
245	
246	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("push");
247	
248	    let work_desc = description(&fx.work, "main");
249	    assert!(
250	        work_desc
251	            .trim_end()
252	            .ends_with(&format!("ochid: /.claude/{agent_at}")),
253	        "restamped:\n{work_desc}"
254	    );
255	    assert_eq!(
256	        chid(&fx.work, "main"),
257	        work_at,
258	        "a restamp keeps the change id"
259	    );
260	    assert_eq!(chid(&fx.bot, "main"), agent_at);
261	    assert!(
262	        description(&fx.bot, "main").contains(&format!("ochid: /{work_at}")),
263	        "the partner names the work commit"
264	    );
265	}
266	
267	/// A feature-bookmark push pins the agent repo to `main`: the work
268	/// repo advances and pushes `feature`, while the agent repo advances
269	/// `main` and grows no `feature` bookmark.
270	#[test]
271	fn push_feature_bookmark_pins_bot_to_main() {
272	    let fx = Fixture::new("push-feature-pin");
273	    jj_ok(&fx.work, &["git", "push", "--named", "feature=@-"]);
274	    let (work_at, agent_at) = make_pair(&fx, "feat: on feature", true);
275	    let bot_main_before = cid(&fx.bot, "main");
276	
277	    let mut params = test_params();
278	    params.bookmark = Some("feature".to_string());
279	    push_in(&mut test_ctx(), &pair(&fx), &both(), &params).expect("push");
280	
281	    assert_eq!(chid(&fx.work, "feature"), work_at);
282	    assert_eq!(cid(&fx.work, "feature"), cid(&fx.work, "feature@origin"));
283	    assert_ne!(cid(&fx.bot, "main"), bot_main_before);
284	    assert_eq!(chid(&fx.bot, "main"), agent_at);
285	    let bot_bookmarks = jj_ok(&fx.bot, &["bookmark", "list"]);
286	    assert!(
287	        !bot_bookmarks.lines().any(|l| l.starts_with("feature:")),
288	        "the agent repo must not grow a 'feature' bookmark:\n{bot_bookmarks}"
289	    );
290	}
291	
292	/// A named bookmark off the work `@-`'s line, on a commit already
293	/// made, is published where it is, a name and no pair, and one on the
294	/// working copy or the root is refused.
295	#[test]
296	fn push_publishes_a_named_bookmark_off_the_line_where_it_is() {
297	    let fx = Fixture::new("push-name");
298	    fs::write(fx.work.join("side.txt"), "side\n").expect("write");
299	    jj_ok(&fx.work, &["commit", "-m", "feat: a side commit"]);
300	    jj_ok(&fx.work, &["bookmark", "create", "side", "-r", "@-"]);
301	    let side = jj_ok(
302	        &fx.work,
303	        &["log", "-r", "side", "--no-graph", "-T", "commit_id"],
304	    );
305	    jj_ok(&fx.work, &["new", "main"]);
306	    let mut params = test_params();
307	    params.repo = Some(fx.work.clone());
308	    params.bookmark = Some("side".to_string());
309	    crate::push::push(&mut test_ctx(), &params).expect("the name is published");
310	    assert_eq!(
311	        crate::jj::remote_bookmark_targets(&fx.work, "origin")
312	            .expect("remote")
313	            .get("side"),
314	        Some(&side)
315	    );
316	
317	    fs::write(fx.work.join("wip.txt"), "wip\n").expect("write");
318	    jj_ok(&fx.work, &["bookmark", "create", "wip", "-r", "@"]);
319	    params.bookmark = Some("wip".to_string());
320	    let err = crate::push::push(&mut test_ctx(), &params)
321	        .expect_err("the working copy")
322	        .to_string();
323	    assert!(err.contains("`vc-x1 commit`"), "{err}");
324	}
325	
326	/// Two bookmarks on the line and none named is refused, and a named
327	/// bookmark that is not on the line is refused too.
328	#[test]
329	fn push_needs_the_bookmark_named_when_the_line_is_ambiguous() {
330	    let fx = Fixture::new("push-ambiguous");
331	    jj_ok(&fx.work, &["bookmark", "create", "second", "-r", "@-"]);
332	    make_pair(&fx, "feat: which line", true);
333	    let err = push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params())
334	        .expect_err("ambiguous")
335	        .to_string();
336	    assert!(err.contains("several bookmarks"), "{err}");
337	
338	    jj_ok(
339	        &fx.work,
340	        &["bookmark", "create", "elsewhere", "-r", "root()"],
341	    );
342	    let mut params = test_params();
343	    params.bookmark = Some("elsewhere".to_string());
344	    let err = push_in(&mut test_ctx(), &pair(&fx), &both(), &params)
345	        .expect_err("not on the line")
346	        .to_string();
347	    assert!(err.contains("not the nearest bookmark"), "{err}");
348	}
349	
350	/// Build a `Run` carrying the ids a completed push would have.
351	fn completion_run(work_chid: String, agent_chid: String) -> Run {
352	    Run {
353	        work: Some(("main".to_string(), work_chid)),
354	        partner: Some(agent_chid),
355	        held: false,
356	    }
357	}
358	
359	/// Happy path: bookmarks at the run's ids, work `@` clean.
360	#[test]
361	fn completion_sanity_pass() {
362	    let fx = Fixture::new("completion-pass");
363	    make_pair(&fx, "feat: pass", true);
364	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("push");
365	    let run = completion_run(chid(&fx.work, "main"), chid(&fx.bot, "main"));
366	    verify_completion(&pair(&fx), &run).expect("passes");
367	}
368	
369	/// Each check fails on its own discrepancy: the work bookmark
370	/// elsewhere, a dirty work `@`, the agent bookmark elsewhere.
371	#[test]
372	fn completion_sanity_fails_on_each_discrepancy() {
373	    let fx = Fixture::new("completion-fail");
374	    make_pair(&fx, "feat: x", true);
375	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("push");
376	    let work_chid = chid(&fx.work, "main");
377	    let agent_chid = chid(&fx.bot, "main");
378	
379	    let run = completion_run("zzzzzzzzzzzz".to_string(), agent_chid.clone());
380	    let msg = verify_completion(&pair(&fx), &run)
381	        .expect_err("work mismatch")
382	        .to_string();
383	    assert!(
384	        msg.contains("work bookmark") && msg.contains("zzzzzzzzzzzz"),
385	        "{msg}"
386	    );
387	
388	    let run = completion_run(work_chid.clone(), "zzzzzzzzzzzz".to_string());
389	    let msg = verify_completion(&pair(&fx), &run)
390	        .expect_err("agent mismatch")
391	        .to_string();
392	    assert!(
393	        msg.contains("agent bookmark") && msg.contains("zzzzzzzzzzzz"),
394	        "{msg}"
395	    );
396	
397	    fs::write(fx.work.join("dirty.txt"), "uncommitted").expect("write dirty");
398	    let run = completion_run(work_chid, agent_chid);
399	    let msg = verify_completion(&pair(&fx), &run)
400	        .expect_err("dirty")
401	        .to_string();
402	    assert!(msg.contains("uncommitted changes"), "{msg}");
403	}
404	
405	/// Rerunning a completed push is safe and changes nothing: the plan
406	/// finds the pair published, the journal folds or is nothing, and
407	/// jj's push reports nothing to do.
408	#[test]
409	fn push_rerun_after_completion_is_a_noop() {
410	    let fx = Fixture::new("push-rerun");
411	    make_pair(&fx, "feat: once", false);
412	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("first push");
413	    let work_after = cid(&fx.work, "main");
414	    let bot_after = cid(&fx.bot, "main");
415	
416	    push_in(&mut test_ctx(), &pair(&fx), &both(), &test_params()).expect("rerun");
417	
418	    assert_eq!(cid(&fx.work, "main"), work_after);
419	    assert_eq!(cid(&fx.bot, "main"), bot_after);
420	    assert_eq!(desc_first_line(&fx.work, "main"), "feat: once");
421	}
422	
423	/// The halves: `-s w` publishes the work commit and leaves the agent
424	/// repo alone, and `-s a` after it completes the agent half, the
425	/// by-hand remainder of a run that stopped after push-work.
426	#[test]
427	fn push_halves_publish_one_side_each() {
428	    let fx = Fixture::new("push-halves");
429	    let (work_at, agent_at) = make_pair(&fx, "feat: in halves", false);
430	    let bot_main_before = cid(&fx.bot, "main");
431	
432	    push_in(
433	        &mut test_ctx(),
434	        &pair(&fx),
435	        &Scope(vec![Side::Work]),
436	        &test_params(),
437	    )
438	    .expect("work half");
439	    assert_eq!(chid(&fx.work, "main"), work_at);
440	    assert_eq!(cid(&fx.work, "main@origin"), cid(&fx.work, "main"));
441	    assert_eq!(
442	        cid(&fx.bot, "main"),
443	        bot_main_before,
444	        "the agent repo is untouched"
445	    );
446	    assert!(!is_empty(&fx.bot, "@"));
447	
448	    push_in(
449	        &mut test_ctx(),
450	        &pair(&fx),
451	        &Scope(vec![Side::Bot]),
452	        &test_params(),
453	    )
454	    .expect("agent half");
455	    assert_eq!(chid(&fx.bot, "main"), agent_at);
456	    assert_eq!(cid(&fx.bot, "main@origin"), cid(&fx.bot, "main"));
457	}
458	
459	/// The halves in the order the pair is completed: `-s a` after
460	/// `commit -s w` commits the journal as the partner and publishes
461	/// `main`, mirroring the commit before it, and `-s w` then publishes
462	/// the work commit, its trailer already naming the partner.
463	#[test]
464	fn push_agent_half_then_work_half() {
465	    let fx = Fixture::new("push-agent-first");
466	    let (work_at, agent_at) = make_pair(&fx, "feat: agent first", false);
467	    let work_main_before = cid(&fx.work, "main");
468	    let work_desc_before = description(&fx.work, "@-");
469	
470	    push_in(
471	        &mut test_ctx(),
472	        &pair(&fx),
473	        &Scope(vec![Side::Bot]),
474	        &test_params(),
475	    )
476	    .expect("agent half");
477	    assert_eq!(chid(&fx.bot, "main"), agent_at);
478	    assert_eq!(cid(&fx.bot, "main@origin"), cid(&fx.bot, "main"));
479	    assert_eq!(
480	        cid(&fx.work, "main"),
481	        work_main_before,
482	        "the work repo is untouched"
483	    );
484	
485	    push_in(
486	        &mut test_ctx(),
487	        &pair(&fx),
488	        &Scope(vec![Side::Work]),
489	        &test_params(),
490	    )
491	    .expect("work half");
492	    assert_eq!(chid(&fx.work, "main"), work_at);
493	    assert_eq!(cid(&fx.work, "main@origin"), cid(&fx.work, "main"));
494	    assert_eq!(
495	        description(&fx.work, "main"),
496	        work_desc_before,
497	        "no restamp: the trailer already names the partner"
498	    );
499	}
500	
501	/// A dry run plans and prints, and moves nothing.
502	#[test]
503	fn push_dry_run_changes_nothing() {
504	    let fx = Fixture::new("push-dry-run");
505	    make_pair(&fx, "feat: dry", false);
506	    let work_main = cid(&fx.work, "main");
507	    let bot_main = cid(&fx.bot, "main");
508	    let mut params = test_params();
509	    params.dry_run = true;
510	    push_in(&mut test_ctx(), &pair(&fx), &both(), &params).expect("dry run");
511	    assert_eq!(cid(&fx.work, "main"), work_main);
512	    assert_eq!(cid(&fx.bot, "main"), bot_main);
513	    assert!(!is_empty(&fx.bot, "@"), "the journal is still in @");
514	}
515	
516	/// `-s p` publishes a plain repo's `@-` on its bookmark, no trailer
517	/// asked for, and new work in `@` stays there.
518	#[test]
519	fn push_por_publishes_the_commit_on_its_bookmark() {
520	    let fx = FixturePor::new("push-por");
521	    fs::write(fx.work.join("plain.txt"), "plain").expect("write");
522	    let at = chid(&fx.work, "@");
523	    let params = CommitParams {
524	        target: Target::Por(fx.work.clone()),
525	        title: Some("feat: plain".to_string()),
526	        body: Some("A body.".to_string()),
527	        closing: None,
528	        opening: None,
529	        advance: crate::commit::Advance::Line,
530	        push: Some(false),
531	        land: None,
532	        skip: None,
533	        dry_run: false,
