538	
539	    let mut params = test_params();
540	    params.scope = RepoScope::Por;
541	    params.repo = Some(fx.work.clone());
542	    push(&mut test_ctx(), &params).expect("push -s p");
543	    assert_eq!(chid(&fx.work, "main"), at);
