}

fn parse(args: &[&str]) -> Result<PushArgs, String> {
    match Cli::try_parse_from(args) {
        Ok(cli) => Ok(cli.args),
        Err(e) => Err(e.to_string()),
    }
}

/// `-s` is required and the other flags default off.
