            (_, Some(file)) => ConfigTarget::Path(file.clone()),
            (Some(scope), None) => ConfigTarget::Scope(scope.clone()),
            (None, None) => ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
        })
    }
}

