    /// The build, `vc-x1 build`'s, with `--dev` or not,, run before
/// Run the build, as `vc-x1 build`, with `--dev` or not, does, then

/// Per-invocation run inputs: the build to run first, its binary, the
/// manifest's version to check it against, and the arguments.
#[derive(Debug)]
pub struct RunParams {
    /// `run` or `run-dev`, prefixing the run's messages.
    pub label: &'static str,
    /// `build.release-bin` or `build.dev-bin`, for a message to point
    /// at.
    pub bin_key: &'static str,
    /// The build, `vc-x1 build`'s or `vc-x1 build-dev`'s, a dry run
    /// when this one is.
    pub build: BuildParams,
    /// The binary to run.
    pub bin: PathBuf,
    /// The manifest's version, `None` when the root has no
    /// `Cargo.toml` to read it from.
    pub version: Option<String>,
    /// The arguments, passed untouched.
    pub args: Vec<OsString>,
    /// Print the build's list and the command, and run nothing.
    pub dry_run: bool,
}

impl TryFrom<&RunArgs> for RunParams {
    type Error = String;

    /// The release: see [`run_params`].
    fn try_from(a: &RunArgs) -> Result<Self, String> {
        run_params(false, a.repo.as_deref(), &a.args, a.dry_run.value)
    }
}

impl TryFrom<&RunDevArgs> for RunParams {
    type Error = String;

    /// The dev build: see [`run_params`].
    fn try_from(a: &RunDevArgs) -> Result<Self, String> {
        run_params(true, a.repo.as_deref(), &a.args, a.dry_run.value)
    }
}

/// Resolve the build, the dev build when `dev`, and its binary. A
/// missing config key is an error here, before anything runs.
pub fn run_params(
    dev: bool,
    repo: Option<&Path>,
    args: &[OsString],
    dry_run: bool,
) -> Result<RunParams, String> {
    let (label, bin_key) = if dev {
        ("run-dev", "build.dev-bin")
    } else {
        ("run", "build.release-bin")
    };
    let mut build = build_params(dev, repo)?;
