255	/// the workspace `-R` named, the words it is given, its own name
256	/// first, and the cursor's index among them when the shell gave one.
257	#[derive(Debug, PartialEq, Eq)]
258	pub struct Forward {
259	    /// `run-dev`'s dev build rather than `run`'s release.
260	    pub dev: bool,
261	    /// The workspace `-R` named, else the current directory's.
262	    pub repo: Option<PathBuf>,
263	    /// The words for the binary, the first standing for its name.
264	    pub words: Vec<String>,
265	    /// The cursor's index in `words`, when the shell passed one.
266	    pub index: Option<usize>,
267	}
268	
269	/// Plan a completion forward from the words a shell passes, the
270	/// program's name first, and the cursor's index among them, or
271	/// `None` when the words are not `run`'s or `run-dev`'s arguments
272	/// and clap completes them itself.
273	///
274	/// - The subcommand is the first word after vc-x1's own flags that
275	///   is `run` or `run-dev`. Any other subcommand is clap's.
276	/// - The subcommand's own options, `--dry-run`, `-R DIR`, `--repo
277	///   DIR`, and `--repo=DIR`, are skipped, and `--` ends them. A word
278	///   at the cursor that starts with `-` before any argument is
279	///   clap's, so `run --d<TAB>` offers `--dry-run`.
280	/// - The cursor on the subcommand or its options is clap's too, so
281	///   only the arguments are forwarded, with the index shifted to
282	///   match.
283	pub fn plan_forward(words: &[String], index: Option<usize>) -> Option<Forward> {
284	    // OK: with no index the shell completes the last word
285	    let cursor = index.unwrap_or(words.len().saturating_sub(1));
286	    let sub = words
287	        .iter()
288	        .enumerate()
289	        .skip(1)
290	        .find(|(_, w)| !w.starts_with('-'))
291	        .map(|(i, _)| i)?;
292	    let dev = match words[sub].as_str() {
293	        "run" => false,
294	        "run-dev" => true,
295	        _ => return None,
296	    };
297	    let mut repo = None;
298	    let mut i = sub + 1;
299	    while i < words.len() && i < cursor {
300	        let w = words[i].as_str();
301	        if w == "--" {
302	            i += 1;
303	            break;
304	        }
305	        if w == "--dry-run" {
306	            i += 1;
307	        } else if w == "-R" || w == "--repo" {
308	            repo = words.get(i + 1).map(PathBuf::from);
309	            i += 2;
310	        } else if let Some(dir) = w.strip_prefix("--repo=") {
311	            repo = Some(PathBuf::from(dir));
312	            i += 1;
313	        } else {
314	            break;
315	        }
316	    }
317	    if cursor < i || (cursor == i && words[i].starts_with('-') && words[i - 1] != "--") {
318	        return None;
319	    }
320	    let mut forwarded = vec![words[0].clone()];
321	    forwarded.extend(words[i..].iter().cloned());
322	    Some(Forward {
323	        dev,
324	        repo,
325	        words: forwarded,
326	        index: index.map(|n| n - (i - 1)),
327	    })
328	}
329	
330	/// Forward a completion request for `run`'s or `run-dev`'s arguments
331	/// to the binary it would run, and exit with its answer. Called by
332	/// `main` before clap's completion, which it leaves alone for every
333	/// other request.
334	///

